"""Build and load the local FAISS index of startable skills.

The index is written at ``rasa train`` into ``skills_index/`` inside the model
snapshot and loaded onto ``ModelBootstrap`` at model load.
"""

from __future__ import annotations

from importlib import resources
from pathlib import Path
from typing import TYPE_CHECKING, Any, Optional

import structlog
from jinja2 import Template

from rasa.core.information_retrieval.faiss import (
    DISTANCE_METRIC_INNER_PRODUCT,
    INDEX_FAISS_FILENAME,
    STORE_JSON_FILENAME,
    FAISS_Store,
)
from rasa.core.information_retrieval.models import Document
from rasa.core.policies.enterprise_search_policy_config import DEFAULT_EMBEDDINGS_CONFIG
from rasa.exceptions import ValidationError
from rasa.mantle.config.agent_spec import AgentSpec, agent_spec_from_config
from rasa.mantle.memory.field import MEMORY_FIELD_TYPE_BOOL, MemoryField
from rasa.mantle.model_archive.bootstrap import resolve_integration_model_groups
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    load_default_skill_catalog,
    load_skill_catalog,
    resolved_memory_field_description,
    routable_target_id_for_skill,
)
from rasa.mantle.skills.skill import Skill
from rasa.shared.constants import MODEL_GROUP_CONFIG_KEY
from rasa.shared.exceptions import InvalidConfigException
from rasa.shared.project_structure import MANTLE_AGENT_FILE, MANTLE_INTEGRATIONS_FILE
from rasa.shared.providers.model_group_validation import (
    validate_model_group_credentials,
)
from rasa.shared.utils.llm import embedder_factory, resolve_model_client_config
from rasa.shared.utils.yaml import read_config_file

if TYPE_CHECKING:
    from rasa.shared.providers.embedding.embedding_client import EmbeddingClient

structlogger = structlog.get_logger()

V2_SKILLS_INDEX_DIR = "skills_index"
LARGE_STARTABLE_CATALOGUE_WITHOUT_RETRIEVAL = 20
SKILL_DOCUMENT_TEMPLATE = (
    resources.files("rasa.mantle.model_archive")
    .joinpath("skill_document_template.jinja2")
    .read_text(encoding="utf-8")
)


def startable_skills(catalog: SkillCatalog) -> list[Skill]:
    """Return startable skills the model may start on an idle turn.

    Engine-managed, disabled, and hidden skills are omitted. Hidden skills stay
    reachable through ``call:`` / ``link:`` / ``resolve_with``, which do not
    use this index.
    """
    startable: list[Skill] = []
    for skill in catalog.skills.values():
        if skill.engine_managed or skill.disabled or skill.hidden:
            continue
        # Skip call-only / internal-only skills so they cannot occupy a top-k slot.
        if routable_target_id_for_skill(skill) is None:
            continue
        startable.append(skill)
    return startable


def skill_retrieval_would_filter(agent: AgentSpec, catalog: SkillCatalog) -> bool:
    """Return whether retrieval can drop a startable skill.

    Retrieval must be on, and that count must be greater than ``num_skills``.
    Hidden, disabled, engine-managed, and non-routable skills are not counted.
    """
    if not agent.skill_retrieval.active:
        return False
    startable_count = len(startable_skills(catalog))
    return startable_count > agent.skill_retrieval.num_skills


def build_skill_documents(
    skills: list[Skill], *, should_embed_memory: bool
) -> list[Document]:
    """Convert startable skills into FAISS documents."""
    return [
        Document(
            text=_skill_document_text(skill, should_embed_memory=should_embed_memory),
            metadata={"skill_id": skill.id},
        )
        for skill in skills
    ]


def load_skills_for_index(snapshot_root: Path) -> SkillCatalog:
    """Load the packaged skill catalog used to decide which skills to index."""
    defaults = load_default_skill_catalog()
    return load_skill_catalog(snapshot_root, defaults=defaults)


def build_skills_embedder(
    agent: AgentSpec, model_groups: list[dict[str, Any]]
) -> "EmbeddingClient":
    """Resolve ``skill_retrieval.embeddings`` into an embedding client.

    An empty embeddings id uses the default embedder. A named model group
    must resolve from packaged integrations and pass credential checks.
    Training fails instead of falling back to the default embedder.
    """
    group_id = agent.skill_retrieval.embeddings
    embeddings_config: Optional[dict[str, Any]] = None
    if group_id:
        if not model_groups:
            raise InvalidConfigException(
                f"skill_retrieval.embeddings names model group '{group_id}', but no "
                f"model_groups are defined in {MANTLE_INTEGRATIONS_FILE}. Define the "
                f"model group there, or clear skill_retrieval.embeddings to use the "
                f"default embedder."
            )
        embeddings_config = resolve_model_client_config(
            {MODEL_GROUP_CONFIG_KEY: group_id},
            "skill_retrieval",
            model_groups=model_groups,
        )
        if embeddings_config is None:
            raise InvalidConfigException(
                f"Could not resolve skill retrieval embeddings model group "
                f"'{group_id}' from {MANTLE_INTEGRATIONS_FILE}."
            )
        try:
            validate_model_group_credentials([embeddings_config])
        except ValidationError as error:
            raise InvalidConfigException(
                f"The skill retrieval embeddings model group '{group_id}' in "
                f"'{MANTLE_INTEGRATIONS_FILE}' has invalid credentials: "
                f"{error.info or error}"
            ) from error
    return embedder_factory(embeddings_config, DEFAULT_EMBEDDINGS_CONFIG)


def build_skills_index(snapshot_root: Path, project_root: Path) -> None:
    """Build the skill FAISS index and write it under ``skills_index/``.

    Skips when retrieval is inactive, or when the startable count is less
    than or equal to ``num_skills``. Embedding or FAISS failures fail
    the train when the index is built.
    """
    agent = _load_agent_from_snapshot(snapshot_root)
    if not agent.skill_retrieval.active:
        _warn_if_large_catalogue_without_retrieval(snapshot_root)
        structlogger.debug("mantle.packaging.skills_index.inactive")
        return

    catalog = load_skills_for_index(snapshot_root)
    if not skill_retrieval_would_filter(agent, catalog):
        _warn_if_active_catalogue_fits_num_skills(agent, catalog)
        return

    skills = startable_skills(catalog)

    documents = build_skill_documents(
        skills, should_embed_memory=agent.skill_retrieval.should_embed_memory
    )
    model_groups = resolve_integration_model_groups(project_root)
    embedder = build_skills_embedder(agent, model_groups)

    try:
        store = FAISS_Store.from_documents(
            documents=documents,
            embeddings=embedder,
            distance_metric=DISTANCE_METRIC_INNER_PRODUCT,
        )
        store.save(snapshot_root / V2_SKILLS_INDEX_DIR)
    except Exception:
        structlogger.exception(
            "mantle.packaging.skills_index.not_populated",
            skill_count=len(documents),
        )
        raise

    structlogger.info(
        "mantle.packaging.skills_index.wrote",
        document_count=len(documents),
    )


def _warn_if_active_catalogue_fits_num_skills(
    agent: AgentSpec, catalog: SkillCatalog
) -> None:
    """Warn when retrieval is on but would return every startable skill."""
    structlogger.warning(
        "mantle.packaging.skills_index.active_catalogue_within_num_skills",
        startable_skill_count=len(startable_skills(catalog)),
        num_skills=agent.skill_retrieval.num_skills,
    )


def _warn_if_large_catalogue_without_retrieval(snapshot_root: Path) -> None:
    """Warn when retrieval is off and the startable count exceeds the default k."""
    catalog = load_skills_for_index(snapshot_root)
    startable_count = len(startable_skills(catalog))
    if startable_count <= LARGE_STARTABLE_CATALOGUE_WITHOUT_RETRIEVAL:
        return
    structlogger.warning(
        "mantle.packaging.skills_index.inactive_large_catalogue",
        startable_skill_count=startable_count,
    )


def load_skills_index(
    snapshot_root: Path,
    agent: AgentSpec,
    model_groups: list[dict[str, Any]],
    catalog: SkillCatalog,
) -> Optional[FAISS_Store]:
    """Load the packaged skills FAISS index, or ``None`` when retrieval cannot filter.

    Returns ``None`` when retrieval is inactive or the startable count is
    less than or equal to ``num_skills``, even if ``skills_index/``
    is present. Fails the load when retrieval would filter and the native files
    are missing or unreadable. Retrain archives that enable retrieval and
    predate the index.
    """
    if not skill_retrieval_would_filter(agent, catalog):
        if agent.skill_retrieval.active:
            structlogger.debug("mantle.skills_index.load.catalogue_within_num_skills")
        else:
            structlogger.debug("mantle.skills_index.load.inactive")
        return None

    index_dir = snapshot_root / V2_SKILLS_INDEX_DIR
    if not _native_skills_index_exists(index_dir):
        raise ValidationError(
            code="mantle.model_archive.skills_index.missing",
            event_info=(
                "Skill retrieval is active and startable skills "
                f"are present, but '{V2_SKILLS_INDEX_DIR}/' is missing from "
                "the model snapshot. Retrain the model."
            ),
        )

    try:
        embedder = build_skills_embedder(agent, model_groups)
        return FAISS_Store.load_native(index_dir, embedder)
    except ValidationError:
        raise
    except Exception as error:
        structlogger.exception("mantle.skills_index.load.failed")
        raise ValidationError(
            code="mantle.model_archive.skills_index.load_failed",
            event_info=(
                "Failed to load the skill retrieval index from "
                f"'{V2_SKILLS_INDEX_DIR}/'. Retrain the model."
            ),
        ) from error


def _native_skills_index_exists(index_dir: Path) -> bool:
    """Return whether both native FAISS persist files are present."""
    return (index_dir / INDEX_FAISS_FILENAME).is_file() and (
        index_dir / STORE_JSON_FILENAME
    ).is_file()


def _load_agent_from_snapshot(snapshot_root: Path) -> AgentSpec:
    """Parse the packaged ``agent.yml`` without expanding env vars."""
    agent_path = snapshot_root / MANTLE_AGENT_FILE
    config_data = (
        read_config_file(str(agent_path), expand_env_vars=False)
        if agent_path.is_file()
        else None
    )
    return agent_spec_from_config(config_data)


def _skill_document_text(skill: Skill, *, should_embed_memory: bool) -> str:
    """Render one skill as searchable text.

    Uses the Jinja layout. Builders cannot override this template.

    Example with ``should_embed_memory=True``::

        Transfer money: Send money to another account.
        confirmed: Whether the user confirmed., allowed values: [True, False]
        reason: Why the SIM is blocked., allowed values: ['lost', 'stolen']
    """
    fields = _memory_field_payloads(skill) if should_embed_memory else []
    return (
        Template(SKILL_DOCUMENT_TEMPLATE)
        .render(
            {
                "skill": {
                    "name": skill.name or skill.id,
                    "description": skill.description or "",
                    "fields": fields,
                }
            }
        )
        .strip()
    )


def _memory_field_payloads(skill: Skill) -> list[dict[str, str | None]]:
    """Return template fields for one skill's memory schema."""
    payloads: list[dict[str, str | None]] = []
    for field_name, field in skill.memory.definition.all_fields().items():
        payloads.append(
            {
                "name": field_name,
                "description": resolved_memory_field_description(skill, field_name),
                "allowed_values": _allowed_values_for_field(field),
            }
        )
    return payloads


def _allowed_values_for_field(field: MemoryField) -> str | None:
    """Return allowed-value text for a memory field schema."""
    if field.type == MEMORY_FIELD_TYPE_BOOL:
        return str([True, False])
    if field.enum_values:
        return str(list(field.enum_values))
    return None
